TLM.f("Tempora/Quad5-0",{"officium":"Dominica de Passione","rule":["no Gloria","Credo","Prefatio=Quad5","Suffragium=Ecclesiæ,Papa;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 42:1-2"},{"k":"text","la":"Júdica me, Deus, et discérne causam meam de gente non sancta: ab hómine iníquo et dolóso éripe me: quia tu es Deus meus et fortitúdo mea."},{"k":"ref","la":"Ps 42:3"},{"k":"text","la":"Emítte lucem tuam et veritátem tuam: ipsa me de duxérunt et adduxérunt in montem sanctum tuum et in tabernácula tua."},{"k":"text","la":"Júdica me, Deus, et discérne causam meam de gente non sancta: ab hómine iníquo et dolóso éripe me: quia tu es Deus meus et fortitúdo mea."}],"Oratio":[{"k":"text","la":"Quǽsumus, omnípotens Deus, famíliam tuam propítius réspice: ut, te largiénte, regátur in córpore; et, te servánte, custodiátur in mente."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos."},{"k":"ref","la":"Hebr 9:11-15"},{"k":"text","la":"Fratres: Christus assístens Póntifex futurórum bonórum, per ámplius et perféctius tabernáculum non manufáctum, id est, non hujus creatiónis: neque per sánguinem hircórum aut vitulórum, sed per próprium sánguinem introívit semel in Sancta, ætérna redemptióne invénta. Si enim sanguis hircórum et taurórum, et cinis vítulæ aspérsus, inquinátos sanctíficat ad emundatiónem carnis: quanto magis sanguis Christi, qui per Spíritum Sanctum semetípsum óbtulit immaculátum Deo, emundábit consciéntiam nostram ab opéribus mórtuis, ad serviéndum Deo vivénti? Et ídeo novi Testaménti mediátor est: ut, morte intercedénte, in redemptiónem eárum prævaricatiónum, quæ erant sub prióri Testaménto, repromissiónem accípiant, qui vocáti sunt ætérnæ hereditátis, in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 142:9, 10"},{"k":"text","la":"Eripe me, Dómine, de inimícis meis: doce me fácere voluntátem tuam"},{"k":"ref","la":"Ps 17:48-49"},{"k":"text","la":"Liberátor meus, Dómine, de géntibus iracúndis: ab insurgéntibus in me exaltábis me: a viro iníquo erípies me."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 128:1-4"},{"k":"text","la":"Sæpe expugnavérunt me a juventúte mea."},{"k":"text","la":"Dicat nunc Israël: sæpe expugnavérunt me a juventúte mea.","mark":"V"},{"k":"text","la":"Etenim non potuérunt mihi: supra dorsum meum fabricavérunt peccatóres.","mark":"V"},{"k":"text","la":"Prolongavérunt iniquitátes suas: Dóminus justus concídit cervíces peccatórum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 8:46-59"},{"k":"text","la":"In illo témpore: Dicébat Jesus turbis Judæórum: Quis ex vobis árguet me de peccáto? Si veritátem dico vobis, quare non créditis mihi? Qui ex Deo est, verba Dei audit. Proptérea vos non audítis, quia ex Deo non estis. Respondérunt ergo Judǽi et dixérunt ei: Nonne bene dícimus nos, quia Samaritánus es tu, et dæmónium habes? Respóndit Jesus: Ego dæmónium non hábeo, sed honorífico Patrem meum, et vos inhonorástis me. Ego autem non quæro glóriam meam: est, qui quærat et júdicet. Amen, amen, dico vobis: si quis sermónem meum serváverit, mortem non vidébit in ætérnum. Dixérunt ergo Judǽi: Nunc cognóvimus, quia dæmónium habes. Abraham mórtuus est et Prophétæ; et tu dicis: Si quis sermónem meum serváverit, non gustábit mortem in ætérnum. Numquid tu major es patre nostro Abraham, qui mórtuus est? et Prophétæ mórtui sunt. Quem teípsum facis? Respóndit Jesus: Si ego glorífico meípsum, glória mea nihil est: est Pater meus, qui gloríficat me, quem vos dícitis, quia Deus vester est, et non cognovístis eum: ego autem novi eum: et si díxero, quia non scio eum, ero símilis vobis, mendax. Sed scio eum et sermónem ejus servo. Abraham pater vester exsultávit, ut vidéret diem meum: vidit, et gavísus est. Dixérunt ergo Judǽi ad eum: Quinquagínta annos nondum habes, et Abraham vidísti? Dixit eis Jesus: Amen, amen, dico vobis, ántequam Abraham fíeret, ego sum. Tulérunt ergo lápides, ut jácerent in eum: Jesus autem abscóndit se, et exívit de templo."}],"Offertorium":[{"k":"ref","la":"Ps 9:1, 118:17, 107"},{"k":"text","la":"Confitébor tibi, Dómine, in toto corde meo: retríbue servo tuo: vivam, et custódiam sermónes tuos: vivífica me secúndum verbum tuum, Dómine."}],"Secreta":[{"k":"text","la":"Hæc múnera, quǽsumus Dómine, et víncula nostræ pravitátis absólvant, et tuæ nobis misericórdiæ dona concílient."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"1 Cor 11:24, 25"},{"k":"text","la":"Hoc corpus, quod pro vobis tradétur: hic calix novi Testaménti est in meo sánguine, dicit Dóminus: hoc fácite, quotiescúmque súmitis, in meam commemoratiónem."}],"Postcommunio":[{"k":"text","la":"Adésto nobis, Dómine, Deus noster: et, quos tuis mystériis recreásti, perpétuis defénde subsídiis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"2671fe5f889feabe":{"t":"Ps 42, 1-2, Ps 42, 3\n(Ps 42, 1-2) Sudi mi Bože, i vodi moju parnicu protiv bezbožna svijeta. Oslobodi me od zlobna i nepravedna čovjeka, jer si ti Bog moj i moja jakost. (Ps 42, 3) Pošalji svoje svjetlo i svoju istinu da me vode na tvoju svetu goru i u tvoje šatore. (Ps 42, 1-2) Sudi mi Bože, i vodi moju parnicu protiv bezbožna svijeta. Oslobodi me od zlobna i nepravedna čovjeka, jer si ti Bog moj i moja jakost. [u vremenu Muke ne govori se Slava Ocu u sklopu Ulazne pjesme]","kn":"(Ps. 42, 1, 2). Sudi mi. Bože, i vodi moju parbu protiv bezbožnog naroda; izbavi me od nepravednih i lukavih ljudi, jer Ti si. Bože, krepost moja. (Ps. 42, 3) Pošalji svoju svjetlost i svoju istinu, neka me izvedu na Tvoju svetu goru i u Tvoje šatore. Sudi mi . . .","knRef":"Kniewald 1942, str. 194–195 (snimka 98) (OCR)"},"d571be308ce588e5":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, pomozi milostivo svojoj obitelji da nas tvoja darežljivost upravlja tjelesno, a tvoja zaštita sačuva duševno.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, svemogući Bože, pogledaj blago svoju obitelj, te je po Tvojem daru upravljaj u tijelu i Tvojom zaštitom čuvaj u duši, po G. n.","knRef":"Kniewald 1942, str. 194–195 (snimka 98) (OCR)"},"a98a57abcad1ed96":{"t":"Heb 9, 11-15\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo: Krist veliki svećenik budućih dobara, nakon što je prešao kroz veći i savršeniji šator, koji nije učinjen rukama, to jest ne pripada ovom svijetu, ušao je, jednom zauvijek, u vječno svetište, ne krvlju jaraca ili junaca, nego vlastitom krvlju, pošto nam je stekao vječni otkup. Ako krv jaraca i volova i posipanje pepelom junice posvećuje okaljane dajući njihovu tijelu zakonsku čistoću, koliko će više krv Krista, koji samoga sebe neokaljana Bogu prinese po Svetom Duhu, očistiti našu savjest od mrtvih djela, da služimo živome Bogu? On je zato posrednik novoga zavjeta, da po smrti, koju je podnio za otkup počinjenih prestupaka u prvom zavjetu, svi izabranici prime obećanu vječnu baštinu u našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi. Pavla apostola Hebrejima (9, 11-15). Braćo! Krist kao veliki svećenik budućih dobara dođe po većem i savršenijem šatoru, koji nije učinjen rukama, to jest od ovih stvorova, niti s krvlju jaraca ili junaca uđe jedamput u svetište i steče vječni otkup, nego vlastitom krvlju. Jer ako krv jaraca i junaca i Rosuti pepeo junice posvećuje okaljane na čistoću tijela, koliko će više krv Kristova, koji samoga sebe neokaljana prinese Bogu Duhom Svetim, očistiti našu savjest od mrtvih djela, da služimo živomu Bogu? I zato je on posrednik Novoga Zavjeta, da po smrti, koju je podnio za otkup učinjenih prestupaka u prvom Zavjetu, prime obećanu vječnu baštinu oni, koji su pozvani u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 194–195 (snimka 98) (OCR)"},"bb7f65fb8984056e":{"t":"Ps 142, 9 i 10\nIzbavi me, Gospodine, od mojih neprijatelja. Uči me vršiti tvoju volju, Gospodine, moj spasitelju od ljutih neprijatelja. Ti ćeš me podignuti nad one koji su ustali na mene. Obranit ćeš me od opaka čovjeka.\n\nPs 128, 1-4\nMnogo su me napadali od moje mladosti. Neka sada rekne Izrael: Mnogo su me napadali od moje mladosti. Ipak me nisu pobijedili. Po mojim su leđima lupali grješnici, dugo su činili svoja zlodjela. Pravedni je Gospodin polomio šije bezbožnika.","kn":"(Ps. 142, 9, 10). Izbavi me od neprijatelja mojih. Gospodine; nauči me vršiti volju Tvoju. (Ps. 17, 48, 49) Otkupitelju moj od ljutih neprijatelja, uzdigao si me nad sve one, koji nasrću na me, oslobodio si me od čovjeka nepravedna.\n\n(Ps. 128, 1-4). Napadali su na me od mladosti moje; napadali su na me od mladosti moje, ali me ne svladaše! Na leđima mojim kovali su grješnici, produžiše neipravde svoje, no pravedni Gospodin skrši šije grješnicima.","knRef":"Kniewald 1942, str. 196–197 (snimka 99) (OCR)"},"7909c2c0b917713c":{"t":"Iv 8, 46-59\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: reče Isus židovskome narodu: »Tko će me od vas okriviti za grijeh? Ako vam govorim istinu, zašto mi ne vjerujete? Tko je od Boga, sluša Božje riječi. Vi ne slušate zato, jer niste od Boga.« Židovi mu odvrate.– »Ne kažemo li mi pravo da si ti Samaritanac i da je đavao u tebi?« Isus odgovori: »U meni nije đavao, nego poštujem svojeg Oca, a vi me grdite. Ja ne tražim svoju slavu, jer ima tko traži i sudi. Zaista, zaista vam kažem: Tko drži moju riječ, neće nikada umrijeti.« – Židovi mu reknu: »Sada znamo da je đavo u tebi. Umro je Abraham, i proroci su umrli, a ti kažeš: Tko drži moju riječ, neće nikada umrijeti. Zar si ti veći od našeg oca Abrahama koji je umro? I proroci su umrli. Za koga ti sebe smatraš?« Isus odgovori: »Ako ja sam sebe slavim, moja je slava ništa. Ali mene slavi moj Otac, a vi za njega kažete da je vaš Bog. Vi ga ne poznajete, a ja ga poznam. Stoga, kad bih rekao da ga ne znam, bio bih lažac kao i vi. Ali ja ga znam i držim njegovu riječ. Vaš je otac Abraham kliktao od želje da vidi moj dan. Vidio je i obradovao se.« Židovi mu tada rekoše: »Još nemaš ni pedeset godina, a da si vidio Abrahama!« Isus im odgovori: »Zaista, zaista vam kažem: Prije nego je Abraham postao, ja jesam.« Tada pograbe kamenje da ga bace na njega, ali se Isus sakrije te izađe iz hrama.","kn":"t Slijedi sveto evanđelje po Ivanu (8, 46-59). U ono vrijeme reče Isus židovskomu narodu: Tko te me od vas okriviti za grijeh? Ako vam govorim istinu, zašto mi ne vjerujete? Tko je od Boga, sluša Božje riječi; vi zato ne slušate, jer nijeste od Boga. Nato mu Židovi odgovoriše: Ne kažemo 11 mi pravo, da si Samaritanac i da imaš đavla? Isus odgovori: Ja nemam đavla, nego poštujem svoga Oca, a vi me pogrdiste. Ali ja ne tražim svoje slave, jer ima koji traži i sudi. Zaista, zaista vam kažem; Tko održi moju riječ, ne će umrijeti nikada. Židovi mu nato rekoše: Sada znamo, da imaš đavla. Abraham je umro 1 proroci, a ti kažeš: Tko održi moju riječ, ne će umrijeti nikada. Zar si ti veći od našega oca Abrahama, koji je umro? I proroci su umrli. Sto misliš: Tko si ti? Isus odgovori: Ako ja sam sebe slavim, moja slava nije ništa; koji mene slavi. Otac je moj, za kojega vi kažete, da je vaš Bog. Ali vi ga ne poznajete, a ja ga znam. Kad bih rekao, da ga ne znam, bio bih lažac kao i vi. Nego znam ga i držim njegovu riječ. Abraham, vaš otac, obradova se. da vidi moj dan; i vidio ga je i radovao se. Tada mu rekoše Židovi: Još nemaš ni pedeset godina i vidio si Abrahama? Isus im odgovori: Zaista, zaista vam kažem:Pr?je nego je Abraham postao, ja jesam. Tada pograbiše kamenje, da bace na njega, ali se Isus sakri i izađe iz hrama.","knRef":"Kniewald 1942, str. 196–197 (snimka 99) (OCR)"},"8a0c2942f6fe9222":{"t":"Ps 110, 1 i 118 i 17 i 107\nHvalit ću te Gospodine, iz svega srca. Učini milost svojemu slugi. Oživi me, da čuvam tvoje riječi. Oživi me po svojoj riječi, Gospodine.","kn":"(Ps. 116, 17, 107). Slavit ću Te, Gospodine, iz svega srca svoga; dopusti sluzi svomu da živi, i držat ću riječi Tvoje: oživi me. Gospodine, Po riječi svojoj!","knRef":"Kniewald 1942, str. 196–197 (snimka 99) (OCR)"},"027274c3a2aff9a7":{"t":"Ovi prinosi, Gospodine, razriješili okove naše zlobe i donijeli nam darove tvojega milosrđa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ovi prinosi, Gospodine, razriješili okove naše zlobe i priklonili nam darove Tvojega milosrđa, po . G. o.","knRef":"Kniewald 1942, str. 330–331 (snimka 166) (OCR)"},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu_ je dostojno i pravedno, pravo i. spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, po Kristu, 1 Gospodinu: našemu: jer Ti si ustanovio spase- I nje ljudskog roda na drvetu križa, da odanle us krsne život, odakle je proizašla smrt, te onaj, koji je na drvetu iznio pobjedu, na drvetu bude i svla- J dan po Kristu, Gospodinu našem, po kojem veličan stvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te i nebeske moći i blaženi Serafini zajedno slave, Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"7ab5864ae2397dc1":{"t":"1 Kor 11 i 24 i 25\nOvo je moje tijelo koje će se za vas predati; ovo je kalež Novoga zavjeta u mojoj krvi, govori Gospodin. Ovo činite na moju uspomenu, kad god budete blagovali.","kn":"(I. Kor. 11, 24). Ovo je tijelo moje, koje se za vas predaje. Ovaj je kalež Novi Zavjet u mojoj krvi, kaže Gospodin. To činite, kadgod budete pili, na moj spomen.","knRef":"Kniewald 1942, str. 196–197 (snimka 99) (OCR)"},"311ca17410185bb2":{"t":"<i>Pomolimo se</i>.\nPomozi nam, Gospodine Bože naš, i nas koje si okrijepio svojim otajstvima štiti neprestanom pomoću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomozi nam. Gospodine, Bože naš, i štiti vječnom obranom nas, koje si okrijepio svojim tajnama, po G. n.","knRef":"Kniewald 1942, str. 196–197 (snimka 99) (OCR)"}}});
